CREATE POLICY crm_history_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='crm-historical-documents' AND EXISTS(SELECT 1 FROM public.crm_documentos_migrados d WHERE d.storage_path=name AND private.has_app_access(auth.uid(),'crm') AND (NOT d.internal_only OR public.is_erp_admin(auth.uid()))));
CREATE POLICY crm_history_files_import ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='crm-historical-documents' AND auth.uid()='6ca0eff8-7393-47bc-9054-9001138bcbc2'::uuid AND public.is_erp_admin(auth.uid()) AND private.has_app_access(auth.uid(),'crm') AND EXISTS(SELECT 1 FROM public.crm_import_runs WHERE id='20261117' AND status='running' AND requested_by=auth.uid()) AND (storage.foldername(name))[1]=auth.uid()::text);